def longest_palindrome(s):
    def pal(i, j):
        if i >= j:
            return True
        return s[i] == s[j] and pal(i + 1, j - 1)

    lo, hi = 0, 1
    for i in range(len(s)):
        for j in range(i, len(s)):
            if j + 1 - i > hi - lo and pal(i, j):
                lo, hi = i, j + 1
    return s[lo:hi]

