def longest_palindrome(s):
    n = len(s)
    pal = [[False] * n for _ in range(n)]
    lo, hi = 0, 1
    for i in range(n - 1, -1, -1):
        for j in range(i, n):
            if s[i] == s[j] and (j - i < 2 or pal[i + 1][j - 1]):
                pal[i][j] = True
                if j + 1 - i > hi - lo:
                    lo, hi = i, j + 1
    return s[lo:hi]

def longest_palindrome(s):
    n = len(s)
    below = [False] * n
    lo, hi = 0, 1
    for i in range(n - 1, -1, -1):
        cur = [False] * n
        for j in range(i, n):
            if s[i] == s[j] and (j - i < 2 or below[j - 1]):
                cur[j] = True
                if j + 1 - i > hi - lo:
                    lo, hi = i, j + 1
        below = cur
    return s[lo:hi]

def longest_palindrome(s):
    n = len(s)
    pal = [False] * n
    lo, hi = 0, 1
    for i in range(n - 1, -1, -1):
        for j in range(n - 1, i - 1, -1):
            pal[j] = s[i] == s[j] and (j - i < 2 or pal[j - 1])
            if pal[j] and j + 1 - i > hi - lo:
                lo, hi = i, j + 1
    return s[lo:hi]

def longest_palindrome(s):
    best_lo, best_hi = 0, 0
    for centre in range(2 * len(s) - 1):
        lo, hi = centre // 2, (centre + 1) // 2
        while lo >= 0 and hi < len(s) and s[lo] == s[hi]:
            lo -= 1
            hi += 1
        # the loop overshoots by one on each side
        if hi - lo - 1 > best_hi - best_lo:
            best_lo, best_hi = lo + 1, hi
    return s[best_lo:best_hi]
